#include <list>
#include <unordered_map>
#include <stdexcept>
#include <optional>

template <typename Key, typename Value>
class LRUCache {
public:
    explicit LRUCache(size_t capacity) : capacity_(capacity) {
        if (capacity == 0) {
            throw std::invalid_argument("LRU cache capacity must be > 0");
        }
    }

    // Returns the value if found, moves it to front (most recently used)
    std::optional<Value> get(const Key& key) {
        auto it = map_.find(key);
        if (it == map_.end()) {
            return std::nullopt;
        }
        // Move accessed item to front
        order_.splice(order_.begin(), order_, it->second);
        return it->second->second;
    }

    // Inserts or updates a key-value pair
    void put(const Key& key, const Value& value) {
        auto it = map_.find(key);

        if (it != map_.end()) {
            // Key exists — update value, move to front
            it->second->second = value;
            order_.splice(order_.begin(), order_, it->second);
            return;
        }

        // Evict LRU if at capacity
        if (order_.size() == capacity_) {
            auto& lru = order_.back();
            map_.erase(lru.first);
            order_.pop_back();
        }

        // Insert new entry at front
        order_.emplace_front(key, value);
        map_[key] = order_.begin();
    }

    // Remove a specific key
    bool erase(const Key& key) {
        auto it = map_.find(key);
        if (it == map_.end()) return false;
        order_.erase(it->second);
        map_.erase(it);
        return true;
    }

    size_t size() const { return map_.size(); }
    size_t capacity() const { return capacity_; }
    bool empty() const { return map_.empty(); }

private:
    size_t capacity_;
    // Front = most recently used, back = least recently used
    std::list<std::pair<Key, Value>> order_;
    std::unordered_map<Key, typename std::list<std::pair<Key, Value>>::iterator> map_;
};
```

Edge cases handled:

- **Zero capacity** — throws at construction. No silent misbehavior.
- **Get on missing key** — returns `std::nullopt` instead of throwing or returning garbage.
- **Put with existing key** — updates in place, promotes to MRU. No duplicate entries.
- **Eviction** — only happens when actually at capacity, removes the correct (LRU) element.
- **Erase on missing key** — returns `false`, no crash.

Complexity: O(1) for `get`, `put`, and `erase`. The `std::list` gives stable iterators and O(1) splice/erase; the hash map gives O(1) lookup.

Here's a practical test suite for a nested JSON parser. I'll assume we're testing a `parseNestedJson` function that takes a string and returns a parsed object, with proper error handling.

```typescript
import { describe, it, expect } from 'vitest';
import { parseNestedJson } from './parseNestedJson';

describe('parseNestedJson', () => {
  // --- Happy path ---

  it('parses a flat object', () => {
    const input = '{"name": "Alice", "age": 30}';
    expect(parseNestedJson(input)).toEqual({ name: 'Alice', age: 30 });
  });

  it('parses deeply nested objects', () => {
    const input = '{"a": {"b": {"c": {"d": "value"}}}}';
    const result = parseNestedJson(input);
    expect(result.a.b.c.d).toBe('value');
  });

  it('parses nested arrays', () => {
    const input = '{"matrix": [[1, 2], [3, 4]]}';
    expect(parseNestedJson(input)).toEqual({ matrix: [[1, 2], [3, 4]] });
  });

  it('parses mixed nested structures', () => {
    const input = '{"users": [{"name": "Bob", "tags": ["admin", "active"]}]}';
    const result = parseNestedJson(input);
    expect(result.users[0].name).toBe('Bob');
    expect(result.users[0].tags).toContain('admin');
  });

  it('handles all JSON primitive types', () => {
    const input = '{"str": "hello", "num": 42, "float": 3.14, "bool": true, "nil": null}';
    const result = parseNestedJson(input);
    expect(result.str).toBe('hello');
    expect(result.num).toBe(42);
    expect(result.float).toBeCloseTo(3.14);
    expect(result.bool).toBe(true);
    expect(result.nil).toBeNull();
  });

  it('handles empty objects and arrays', () => {
    const input = '{"empty_obj": {}, "empty_arr": []}';
    expect(parseNestedJson(input)).toEqual({ empty_obj: {}, empty_arr: [] });
  });

  // --- Edge cases ---

  it('handles unicode and escaped characters', () => {
    const input = '{"msg": "hello\\nworld", "emoji": "\\u2603"}';
    const result = parseNestedJson(input);
    expect(result.msg).toBe('hello\nworld');
    expect(result.emoji).toBe('☃');
  });

  it('handles keys with special characters', () => {
    const input = '{"key with spaces": 1, "key.with.dots": 2}';
    const result = parseNestedJson(input);
    expect(result['key with spaces']).toBe(1);
    expect(result['key.with.dots']).toBe(2);
  });

  it('handles large numbers', () => {
    const input = '{"big": 9007199254740991}';
    expect(parseNestedJson(input).big).toBe(Number.MAX_SAFE_INTEGER);
  });

  // --- Depth limits (if your parser enforces them) ---

  it('rejects nesting beyond max depth', () => {
    // 128 levels deep
    const deep = '{"a":'.repeat(128) + '1' + '}'.repeat(128);
    expect(() => parseNestedJson(deep, { maxDepth: 64 })).toThrow(/depth/i);
  });

  // --- Error handling ---

  it('throws on invalid JSON', () => {
    expect(() => parseNestedJson('{not valid}')).toThrow();
  });

  it('throws on trailing commas', () => {
    expect(() => parseNestedJson('{"a": 1,}')).toThrow();
  });

  it('throws on single quotes', () => {
    expect(() => parseNestedJson("{'a': 1}")).toThrow();
  });

  it('throws on empty string input', () => {
    expect(() => parseNestedJson('')).toThrow();
  });

  it('throws on non-string input', () => {
    // @ts-expect-error testing runtime guard
    expect(() => parseNestedJson(null)).toThrow();
    // @ts-expect-error testing runtime guard
    expect(() => parseNestedJson(undefined)).toThrow();
  });

  it('throws on incomplete JSON', () => {
    expect(() => parseNestedJson('{"a": {')).toThrow();
  });
});
```

Key decisions in this test suite:

- Tests are grouped by concern: happy path, edge cases, depth limits, errors.
- Each test checks one specific behavior — easy to diagnose failures.
- The depth limit test assumes an optional `maxDepth` config. If your parser doesn't have one, drop it or add it (you should — unbounded recursion is a DoS vector).
- Error tests verify the parser rejects malformed input rather than returning garbage.

Adapt the import path and function signature to match your actual implementation. If you're writing the parser from scratch rather than wrapping `JSON.parse`, you'll also want tests for whitespace handling, number parsing edge cases (leading zeros, `-0`, exponents), and duplicate keys.
